from part2 import add, P

add(id="swedes", name="Swedes and Geats", type="peoples and petty kingdoms", yearsActive="c. 400–c. 1000",
 summary="The Svear of the Mälaren region around Uppsala and the Geats to their south, ruled by petty kings whose mound burials and trade routes led east into Russia.",
 description="Around Uppsala the Svear built royal mounds in the sixth century, and boat graves at Vendel and Valsgärde held rich weapons. Helgö and then Birka (from c. 750) were trading towns, and Swedish Vikings, the Rus, travelled by river to the Caspian and Constantinople. Gotland's farmers grew rich from this trade.",
 conflicts="Wars between Svear and Geats are echoed in Beowulf; eastern raids and trading expeditions.",
 leaders="Semi-legendary Ynglings such as Ottar and Adils; Björn at Birka, who received Ansgar (c. 829).",
 religion="Norse paganism with the temple at Uppsala; Ansgar's mission to Birka (c. 829) had little lasting effect.",
 culture="Farms, assemblies (things), runestones; silver hoards on Gotland include many Arab dirhams.",
 literature="Beowulf's hero is a Geat; the Rök runestone (c. 800) carries the longest runic inscription.",
 art="Vendel-style helmets and Gotland picture stones.",
 ideas="The thing assembly made law by consensus of free men.",
 science="Expert boat-building and navigation on the Baltic and Russian rivers.",
 story=[{"title":"The Rök Stone","text":"Around 800 a father named Varin carved more than 700 runes on a stone in Östergötland for his dead son Vämod. Scholars still argue whether it tells of heroic battles or of cosmic fears about a coming cold winter."}],
 images=[("Rök runestone","Rök runestone (c. 800)","culture"),
         ("Gamla Uppsala royal mounds","Royal mounds at Gamla Uppsala (6th century)","art")],
 sources="Encyclopaedia Britannica, 'Sweden: history'; P. Sawyer, The Making of Sweden (1988).")

add(id="danes", name="Danes", type="kingdom", yearsActive="c. 500–present (as Denmark)",
 summary="The people of Jutland and the Danish islands, whose kings built the Danevirke against the Franks and whose Viking armies conquered much of England in the ninth century.",
 description="By 700 a Danish kingdom controlled the trading town of Ribe; King Godfred fortified the Danevirke and founded Hedeby around 808 to rival the Franks. Danish fleets raided Frisia and England, and the Great Heathen Army of 865 conquered the Danelaw.",
 conflicts="Godfred's war with Charlemagne (804–810); raids on Frisia and England; the Great Heathen Army (865–878).",
 leaders="Ongendus (fl. 710); Godfred (d. 810); Horik I (d. 854).",
 religion="Norse paganism; Ansgar built churches at Hedeby and Ribe in the 850s.",
 culture="Trading towns at Ribe and Hedeby; farms in longhouses; the earthwork Danevirke across Jutland.",
 literature="Runic inscriptions; Frankish annals record Danish kings.",
 art="Ship burials; Borre and Jelling-style animal ornament.",
 ideas="Royal power over trade and coinage began at Hedeby.",
 science="Clinker-built longships with keels and sails.",
 story=[{"title":"Godfred's Wall","text":"In 808 Godfred ordered a rampart across the base of Jutland from sea to sea, with a single gate for wagons. Charlemagne's annalists noted it nervously; parts of the Danevirke still stand."}],
 images=[("Danevirke","Danevirke rampart","culture"),
         ("Hedeby Viking houses","Reconstructed houses at Hedeby","art")],
 sources="Encyclopaedia Britannica, 'Denmark: history'; E. Roesdahl, The Vikings (1987).")

add(id="norway", name="Norse kingdoms (Norway)", type="petty kingdoms", yearsActive="c. 500–872; Kingdom of Norway c. 872 onward",
 nameByTick={"800":"Northmen (Norse petty kingdoms)","900":"Kingdom of Norway"},
 summary="The petty kingdoms along Norway's coast, home of many Vikings, which Harald Fairhair united around 872 after the battle of Hafrsfjord.",
 description="Norway's 'north way' coast was divided among chieftains and petty kings. From 793 Norwegian Vikings raided Lindisfarne, Scotland and Ireland and settled the Northern Isles, the Faroes and, from about 870, Iceland. Harald Fairhair's victory at Hafrsfjord made him king over most of the west coast, and some opponents left for Iceland.",
 conflicts="Raid on Lindisfarne (793); settlement of Dublin (841); Hafrsfjord (c. 872).",
 leaders="Harald Fairhair (c. 872–930).",
 religion="Norse paganism; the Oseberg ship burial (834) shows elite rituals.",
 culture="Farms on the coast and fjords; regional things; slaves and trade in furs and walrus ivory with the Sámi.",
 literature="Ottar of Hålogaland described Norway to King Alfred (c. 890); later sagas tell of Harald.",
 art="The Oseberg and Gokstad ship burials, with carved wagons and sleds.",
 ideas="Settlers carried the thing to Iceland, founding the Althing in 930.",
 science="Ocean-going longships and knarrs that reached Iceland and the Faroes.",
 story=[{"title":"The Vow of the Hair","text":"Saga tradition says the princess Gyda refused Harald until he ruled all of Norway, so he vowed not to cut his hair until he did. Ten years later, after Hafrsfjord, he had it cut and became Harald Fairhair."}],
 images=[("Oseberg ship","Oseberg ship (buried 834), Viking Ship Museum, Oslo","art"),
         ("Hafrsfjord swords monument","Sverd i fjell monument at Hafrsfjord","culture")],
 sources="Encyclopaedia Britannica, 'Norway: history', 'Harald I'; P. Sawyer (ed.), Oxford Illustrated History of the Vikings (1997).")

add(id="saami", name="Sámi", type="people", yearsActive="ancient–present",
 summary="The indigenous people of northern Fennoscandia, hunters, fishers and traders whose way of life stretched across the far north of Norway, Sweden, Finland and Russia.",
 description="In the early Middle Ages the Sámi lived across a much wider area than today, hunting wild reindeer, fishing and trapping. Norse chieftains such as Ottar took tribute from them in furs, feathers and walrus hide. Large-scale reindeer herding came later.",
 conflicts="Tribute taking by Norse chieftains and later by Karelians.",
 leaders="Organized in siida communities rather than kingdoms.",
 religion="Shamanism with the noaidi (shaman) and drum, and sacred stones (sieidi).",
 culture="Siida groups moved seasonally between hunting and fishing grounds; Sámi languages are Uralic.",
 literature="Ottar's account to Alfred (c. 890) and Procopius's 'Skrithiphinoi' (skiing Finns) are early mentions.",
 art="Decorated drums and bone tools; joik song.",
 ideas="Land was held by the siida as a group.",
 science="Skis and sledges for travel; deep knowledge of reindeer and Arctic conditions.",
 story=[{"title":"Ottar's Tribute","text":"Ottar told King Alfred that each Sámi paid him by rank: marten skins, reindeer hides, bird feathers, whale bone and ship ropes made from walrus and seal hide."}],
 images=[("Sami drum","Sámi drum","culture"),
         ("Sami people 1900","Sámi family in northern Scandinavia","art")],
 sources="Encyclopaedia Britannica, 'Sami'; N. Kent, The Sámi Peoples of the North (2014).")

add(id="finno-ugric", name="Finno-Ugric peoples", type="peoples", yearsActive="ancient–present",
 summary="Uralic-speaking peoples of the northern forests—Finns, Karelians, Ests, Veps, Mari, Mordvins, Permians and others—who traded furs with Vikings, Bulgars and Arabs.",
 description="Across the taiga from the Baltic to the Urals lived farming and hunting peoples speaking Uralic languages. Finns and Ests had hill-forts and traded with Scandinavia; Veps and Chuds met the Rus on the routes to Novgorod; Mari, Mordvins and Permians supplied furs to Volga Bulgar markets.",
 conflicts="Raids and tribute exchanges with Vikings and Rus; Chuds took part in calling the Rus to Novgorod (862) according to the Primary Chronicle.",
 leaders="Tribal elders and chieftains; no states in this period.",
 religion="Animist and shamanic beliefs with sacred groves; the Mari kept theirs into modern times.",
 culture="Slash-and-burn farming, hunting and fishing; hill-forts in Finland and Estonia.",
 literature="Oral epic traditions later collected as the Kalevala.",
 art="Permian animal-style bronzes; Finnish and Estonian jewellery.",
 ideas="Their languages, Finnish, Estonian, Hungarian among them, form the Uralic family.",
 science="Bog iron smelting and expert forest crafts.",
 story=[{"title":"The Calling of the Rus","text":"The Primary Chronicle claims that Slavs and Chuds, tired of quarrels, invited Rurik's Varangians: 'Our land is great and rich, but there is no order in it; come and rule over us.'"}],
 images=[("Permian animal style","Permian animal-style bronze","art"),
         ("Kalevala Gallen-Kallela","Akseli Gallen-Kallela's painting of Kalevala, the Finnish epic","culture")],
 sources="Encyclopaedia Britannica, 'Finno-Ugric peoples'; Russian Primary Chronicle.")

add(id="avars", name="Avar Khaganate", type="khaganate", yearsActive="567–c. 822",
 summary="A nomadic khaganate from the Eurasian steppe that ruled the Carpathian Basin for two and a half centuries, besieged Constantinople in 626 and fell to Charlemagne in the 790s.",
 description="The Avars arrived on the Danube in the 560s and with the Lombards destroyed the Gepids in 567, then took the Carpathian Basin. They extorted tribute from Byzantium, led Slavs into the Balkans and besieged Constantinople with the Persians in 626. Charlemagne's armies and the Bulgars broke them in 791–803, carrying off their treasure, the Ring.",
 conflicts="Destruction of the Gepids (567); siege of Constantinople (626); Charlemagne's Avar wars (791–796).",
 leaders="Bayan I (562–c. 602).",
 religion="Steppe Tengrism; some converted to Christianity after Frankish conquest.",
 culture="A horse-riding elite ruled Slavs and others; they brought the stirrup to Europe.",
 literature="Byzantine and Frankish sources only.",
 art="Gilded bronze belt fittings with griffins and tendrils.",
 ideas="Their rule over Slavic subjects helped spread Slavs through central Europe and the Balkans.",
 science="The iron stirrup, which they introduced to Europe.",
 story=[{"title":"The Treasure of the Ring","text":"In 796 Frankish troops broke into the Avars' circular fortified camp, the Ring, and found so much gold that Einhard wrote the Franks, once poor, became rich from it overnight."}],
 images=[("Avar belt","Avar belt fittings","art"),
         ("Avar stirrup","Avar stirrups","culture")],
 sources="Encyclopaedia Britannica, 'Avar'; W. Pohl, The Avars (2018).")

add(id="khazars", name="Khazar Khaganate", type="khaganate", yearsActive="c. 650–969",
 summary="A Turkic khaganate on the lower Volga and North Caucasus that blocked Arab expansion north, controlled steppe trade, and whose ruling elite adopted Judaism.",
 description="Emerging from the Western Turkic Khaganate, the Khazars ruled from Itil on the Volga delta over Bulgars, Alans, Magyars and Slavs. They fought the Arabs in two long wars in the Caucasus and allied with Byzantium. Around 800 the khagan and nobles adopted Judaism. Sviatoslav of Kyiv destroyed the state in 965–969.",
 conflicts="Arab-Khazar wars (642–652, 722–737); Rus attacks culminating in 965–969.",
 leaders="Khagan Bulan, who converted (c. 740–800 by different accounts); Joseph (mid-10th century).",
 religion="Judaism among the elite, with Christians, Muslims and pagans as subjects, judged by their own courts.",
 culture="Dual kingship of a sacred khagan and a military bek; capital Itil with markets and customs posts.",
 literature="The Khazar Correspondence (10th century) between Hasdai ibn Shaprut of Córdoba and King Joseph.",
 art="Saltovo-Mayaki culture fortresses and ceramics.",
 ideas="Religious tolerance under a multi-faith legal system.",
 science="Brick fortress at Sarkel built by Byzantine engineers (c. 840).",
 story=[{"title":"A Letter from Córdoba","text":"A Jewish minister of the caliph of Córdoba heard of a Jewish kingdom in the east and wrote to its king. Joseph's reply described his realm and its conversion, a letter preserved for a thousand years."}],
 images=[("Sarkel fortress","Sarkel fortress plan / excavation","culture"),
         ("Khazar Khaganate map","Map of the Khazar Khaganate around 820","culture")],
 sources="Encyclopaedia Britannica, 'Khazar'; P. Golden et al. (eds.), The World of the Khazars (2007).")

add(id="bulgaria", name="Bulgar Khanate (First Bulgarian Empire)", type="khanate", yearsActive="681–1018",
 summary="The state founded by Asparukh's Bulgars south of the Danube in 681, which became a Slavic-speaking Christian empire rivalling Byzantium.",
 description="Fleeing the Khazars, Bulgar Khan Asparukh crossed the Danube and defeated Byzantium in 680–681. From Pliska the khans ruled Slavs and Bulgars. Krum killed Emperor Nikephoros I (811), Boris I converted (864), and Simeon I (893–927) made the Slavonic alphabet and Preslav school the heart of Orthodox Slavic culture.",
 conflicts="Battle of Ongal (680); Krum's victory at Pliska (811); Simeon's wars with Byzantium.",
 leaders="Asparukh (681–700); Tervel (700–721), who helped break the Arab siege of Constantinople; Krum (803–814); Boris I (852–889); Simeon I (893–927).",
 religion="Tengrism, then Orthodox Christianity from 864.",
 culture="A Turkic Bulgar elite merged with the Slavic majority; Old Church Slavonic became the literary language.",
 literature="The Preslav and Ohrid schools developed the Cyrillic script; Clement and Naum translated scripture.",
 art="The Madara Rider rock relief (8th century); the Golden Church at Preslav.",
 ideas="Christianity in a Slavic tongue rather than Greek or Latin.",
 science="Preslav ceramics workshops.",
 story=[{"title":"Krum's Cup","text":"After killing Emperor Nikephoros in 811, Krum had the emperor's skull lined with silver and used it as a drinking cup for his nobles."}],
 images=[("Madara Rider","Madara Rider relief (8th century)","art"),
         ("Pliska","Ruins of Pliska, the first Bulgarian capital","culture")],
 sources="Encyclopaedia Britannica, 'Bulgaria: history'; J. V. A. Fine, The Early Medieval Balkans (1983).")

add(id="volga-bulgars", name="Volga Bulgars", type="khanate", yearsActive="c. 750–1240",
 summary="A Bulgar state at the junction of the Volga and Kama rivers that controlled the fur trade between the northern forests and the Islamic world, and converted to Islam in 922.",
 description="Bulgars who moved north after the break-up of Old Great Bulgaria settled on the middle Volga under Khazar overlordship. Their towns Bolghar and Suvar became markets where Rus and Finnic hunters sold furs, slaves and honey for Arab silver.",
 conflicts="Subjection to the Khazars until the 10th century.",
 leaders="Almış (fl. 922), who asked the caliph for Islamic teachers.",
 religion="Tengrism until the conversion to Islam in 922.",
 culture="Trading towns and farming; Bulgar language survives as modern Chuvash.",
 literature="Ibn Fadlan's account of his embassy (921–922).",
 art="Metalwork; later mosques at Bolghar.",
 ideas="The northernmost Muslim state of its time.",
 science="Ibn Fadlan describes the aurora and the short summer nights.",
 story=[{"title":"Ibn Fadlan on the Volga","text":"Ibn Fadlan, sent by the Abbasid caliph in 921, watched a Rus chieftain's ship burial on the Volga and wrote down every detail, one of the few eyewitness accounts of Viking funerals."}],
 images=[("Bolghar","Ruins of Bolghar on the Volga","culture"),
         ("Ibn Fadlan","Ibn Fadlan's journey","art")],
 sources="Encyclopaedia Britannica, 'Bulgar'; Ibn Fadlan, Mission to the Volga.")

add(id="lombards", name="Lombard Kingdom and duchies", type="kingdom", yearsActive="568–774 (southern duchies to 1077)",
 summary="A Germanic people who invaded Italy in 568, ruling from Pavia until Charlemagne conquered the kingdom in 774, while the duchy of Benevento stayed independent in the south.",
 description="Led by Alboin, the Lombards crossed the Alps in 568 and took most of Italy from the exhausted Byzantines. Their kingdom centred on Pavia, with semi-independent duchies at Spoleto and Benevento. King Rothari issued a law code (643), and Liutprand expanded at Byzantine and papal expense. Pope Stephen II called the Franks, and Charlemagne took the Iron Crown in 774.",
 conflicts="Invasion of 568; wars with Byzantium and the papacy; Frankish conquest (774).",
 leaders="Alboin (560–572); Agilulf and Queen Theodelinda (c. 590–616); Rothari (636–652); Liutprand (712–744); Desiderius (756–774); Arechis II of Benevento (758–787).",
 religion="Arian and pagan at first, Catholic by the late 7th century through Theodelinda's influence.",
 culture="Their name survives in Lombardy; Lombard law mixed Germanic custom and Roman practice.",
 literature="Paul the Deacon's History of the Lombards (c. 790); Edictum Rothari (643).",
 art="The Tempietto Longobardo at Cividale; the Iron Crown of Lombardy at Monza.",
 ideas="The Lombard notaries of Pavia kept written law alive, leading later to the law school of Bologna.",
 science="Paul the Deacon passed on classical learning at Charlemagne's court.",
 story=[{"title":"Rosamund's Revenge","text":"Paul the Deacon says Alboin made his wife Rosamund drink from a cup made of her father's skull. She had him murdered in his bed in 572."}],
 images=[("Tempietto longobardo Cividale","Tempietto Longobardo, Cividale del Friuli (8th century)","art"),
         ("Iron Crown of Lombardy","Iron Crown of Lombardy, Monza","culture")],
 sources="Encyclopaedia Britannica, 'Lombard'; C. Wickham, Early Medieval Italy (1981).")

add(id="slavs", name="Slavic tribes", type="tribal peoples", yearsActive="c. 500–present",
 nameByTick={"700":"Slavic tribes (Polanes, Krivichs, Severians)"},
 summary="The Slavic peoples who spread from eastern Europe across the Balkans, central Europe and the Russian forests in the sixth and seventh centuries, living in tribes that later formed Poland, Bohemia, Rus and Balkan states.",
 description="Byzantine writers first describe Sclaveni and Antes on the lower Danube in the sixth century. Under Avar rule and on their own, Slavs settled the Balkans, Bohemia, the Elbe region and the forests north to Lake Ilmen. Tribes such as the Polanes on the Vistula, the Krivichs and the Severians lived in fortified settlements (grods) with farming and trade.",
 conflicts="Raids on Byzantium; Samo's union defeated the Franks at Wogastisburg (631).",
 leaders="Samo, Frankish merchant who led a Slavic union (c. 623–658).",
 religion="Slavic paganism with Perun, the thunder god; Christianized from the ninth century on.",
 culture="Farming villages, timber forts, pit houses; Proto-Slavic was still a common language.",
 literature="Procopius and Pseudo-Maurice's Strategikon describe early Slavs.",
 art="Prague-type pottery; temple rings worn by women.",
 ideas="Village assemblies (veche) took decisions among free men.",
 science="Ard ploughs and crop rotation in forest clearings.",
 story=[{"title":"Samo's Answer","text":"When a Frankish envoy told Samo that Christians owed King Dagobert service as dogs owe their masters, Samo replied that if the Franks were God's servants, the Slavs were his dogs, and would bite."}],
 images=[("Slavic gord reconstruction","Reconstructed Slavic fortified settlement (gord)","culture"),
         ("Zbruch idol","Zbruch idol, a carved Slavic pagan pillar","art")],
 sources="Encyclopaedia Britannica, 'Slav'; F. Curta, The Making of the Slavs (2001).")

add(id="great-moravia", name="Great Moravia", type="principality", yearsActive="833–c. 906",
 summary="The first major West Slavic state, centred on the Morava river, where Cyril and Methodius created a Slavonic liturgy before Magyar invasions destroyed it around 906.",
 description="Mojmír I united Moravian tribes around 833, and Rastislav asked Byzantium for Slavic-speaking missionaries. Cyril and Methodius arrived in 863 with the new Glagolitic alphabet. Svatopluk I (870–894) expanded the state into Bohemia, Pannonia and southern Poland. After his death the realm broke up under Magyar attack.",
 conflicts="Wars with East Francia; Magyar invasions (c. 902–907).",
 leaders="Mojmír I (833–846); Rastislav (846–870); Svatopluk I (870–894).",
 religion="Christianity, with competing Frankish Latin and Byzantine Slavonic missions.",
 culture="Fortified centres at Mikulčice and Staré Město with stone churches.",
 literature="The Glagolitic alphabet; Slavonic translations of scripture and liturgy.",
 art="Gold and silver jewellery (gombíky buttons) from Mikulčice graves.",
 ideas="Liturgy in the people's language, approved by Pope Adrian II (868).",
 science="Advanced ironworking and fortified towns.",
 story=[{"title":"Svatopluk's Rods","text":"Byzantine emperor Constantine VII told how the dying Svatopluk gave his three sons three rods, showing that bound together they could not be broken. They quarrelled anyway, and the Magyars took the realm."}],
 images=[("Glagolitic alphabet","Glagolitic alphabet created for the Moravian mission","culture"),
         ("Mikulčice","Excavated Great Moravian stronghold at Mikulčice","art")],
 sources="Encyclopaedia Britannica, 'Great Moravia'; F. Curta, Eastern Europe in the Middle Ages (2019).")

add(id="balts", name="Baltic tribes", type="tribal peoples", yearsActive="ancient–13th century",
 summary="The Baltic-speaking Prussians, Curonians, Lithuanians and others on the south-east Baltic coast, who traded amber and stayed pagan longer than any other Europeans.",
 description="Baltic tribes lived between the Vistula and the Daugava in hill-forts and farming villages. They traded amber and furs with Vikings, who founded trading posts like Truso and Grobiņa among them. The Prussians killed the missionary Adalbert of Prague in 997.",
 conflicts="Viking raids on Curonia (9th century); later wars with Poles and crusaders.",
 leaders="Tribal chieftains and priests.",
 religion="Baltic paganism with sacred groves and thunder god Perkūnas.",
 culture="Hill-forts, amber workshops; languages ancestral to Lithuanian, Latvian and Old Prussian.",
 literature="Wulfstan's voyage to Truso (c. 890) describes Prussian funerals.",
 art="Bronze ornaments and amber beads.",
 ideas="Their languages preserve many ancient Indo-European features.",
 science="Fermented mead and horse-racing funerals described by Wulfstan.",
 story=[{"title":"The Race for the Dead Man's Goods","text":"Wulfstan told King Alfred that when a rich Prussian died, his goods were laid out in heaps along a course, and horsemen raced for them, the fastest winning the largest heap."}],
 images=[("Baltic amber","Baltic amber","culture"),
         ("Apuolė hillfort","Apuolė hill-fort in Lithuania","art")],
 sources="Encyclopaedia Britannica, 'Balt'; M. Gimbutas, The Balts (1963).")
